// Tracing for model calls with the OpenTelemetry GenAI semantic conventions (status: Development; names changed
// during 2026, re-check https://github.com/open-telemetry/semantic-conventions-genai when upgrading).
// Generated by `eos scaffold llm-otel`; yours to edit. Prompts/outputs are NOT recorded: they are opt-in
// attributes holding personal data. Ref: .eos/packs/ref/llm/observability-otel.md
//
//   const r = await withLlmSpan({ operation: "chat", provider: "openai", model: MODEL, promptName: p.id,
//     promptVersion: p.version, maxTokens: 600 }, async (span) => {
//     const res = await client.responses.create({ model: MODEL, input, max_output_tokens: 600 });
//     recordUsage(span, { responseModel: res.model, inputTokens: res.usage?.input_tokens,
//       outputTokens: res.usage?.output_tokens, cacheReadTokens: res.usage?.input_tokens_details?.cached_tokens });
//     return res;
//   });
import { SpanKind, SpanStatusCode, trace, type Span } from "@opentelemetry/api";

const tracer = trace.getTracer("app.genai");

export type LlmCall = {
  operation: "chat" | "generate_content" | "embeddings" | "text_completion";
  provider: string; // "openai", "anthropic", "gcp.gen_ai", …
  model: string;
  promptName?: string;
  promptVersion?: string | number;
  maxTokens?: number;
  attributes?: Record<string, string | number | boolean>;
};

export async function withLlmSpan<T>(call: LlmCall, fn: (span: Span) => Promise<T>): Promise<T> {
  return tracer.startActiveSpan(`${call.operation} ${call.model}`, { kind: SpanKind.CLIENT }, async (span) => {
    span.setAttributes({
      "gen_ai.operation.name": call.operation,
      "gen_ai.provider.name": call.provider,
      "gen_ai.request.model": call.model,
      ...(call.maxTokens !== undefined && { "gen_ai.request.max_tokens": call.maxTokens }),
      ...(call.promptName && { "gen_ai.prompt.name": call.promptName }),
      ...(call.promptVersion !== undefined && { "gen_ai.prompt.version": String(call.promptVersion) }),
      ...call.attributes,
    });
    try {
      return await fn(span);
    } catch (err) {
      span.setAttribute("error.type", err instanceof Error ? err.name : "Error");
      span.setStatus({ code: SpanStatusCode.ERROR });
      throw err;
    } finally {
      span.end();
    }
  });
}

export function recordUsage(
  span: Span,
  u: { responseModel?: string; inputTokens?: number; outputTokens?: number; cacheReadTokens?: number; finishReasons?: string[] },
): void {
  if (u.responseModel) span.setAttribute("gen_ai.response.model", u.responseModel);
  if (u.inputTokens !== undefined) span.setAttribute("gen_ai.usage.input_tokens", u.inputTokens);
  if (u.outputTokens !== undefined) span.setAttribute("gen_ai.usage.output_tokens", u.outputTokens);
  if (u.cacheReadTokens !== undefined) span.setAttribute("gen_ai.usage.cache_read.input_tokens", u.cacheReadTokens);
  if (u.finishReasons?.length) span.setAttribute("gen_ai.response.finish_reasons", u.finishReasons);
}
